package api

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/ahmadrezamusthafa/meta-orchestrator/internal/pullrequest"
	"github.com/ahmadrezamusthafa/meta-orchestrator/pkg/types"
)

// Each pull request's Summary is generated by the analysis model from that repository's diff and
// the task (see pullrequest.SummaryPrompt). It is cached in the task's artifacts under a hash of
// the prompt, so it is generated again only when the diff, the task or the report changes. The
// report's Summary stays the fallback when no model is configured or the call fails.

// prSummaryTimeout bounds one summary call; the drafts of a task are summarized in parallel.
const prSummaryTimeout = 45 * time.Second

// prSummaryCache is a generated summary as stored in the task's artifacts.
type prSummaryCache struct {
	Key       string    `json:"key"`
	Summary   string    `json:"summary"`
	Model     string    `json:"model"`
	Generated time.Time `json:"generated"`
}

// prSummaryDoc is where a repository's generated summary is cached.
func prSummaryDoc(repo string) string { return "pull-requests/summary-" + safeFileName(repo) + ".json" }

// summarizeDrafts sets each draft's Summary from its cached or (with generate) newly generated
// summary, and SummarySource accordingly.
func (r *Router) summarizeDrafts(ctx context.Context, t *types.Task, drafts []*prDraft, generate bool) {
	var wg sync.WaitGroup
	for _, d := range drafts {
		d.SummarySource = "report"
		if d.Files == 0 || d.patch == "" {
			continue
		}
		wg.Add(1)
		go func(d *prDraft) {
			defer wg.Done()
			if s := r.prSummary(ctx, t, d, generate); s != "" {
				d.in.Summary, d.SummarySource = s, "generated"
			}
		}(d)
	}
	wg.Wait()
}

// prSummary returns the draft's generated summary, or "" when there is none.
func (r *Router) prSummary(ctx context.Context, t *types.Task, d *prDraft, generate bool) string {
	var others []string
	for _, rel := range d.in.Related {
		others = append(others, rel.Repo)
	}
	system, user := pullrequest.SummaryPrompt(pullrequest.SummaryInput{Title: t.Title, Description: t.Description,
		AcceptanceCriteria: d.in.AcceptanceCriteria, Repo: d.Repo, OtherRepos: others, Commits: d.in.Commits,
		ReportChanges: d.in.Details, Patch: d.patch, PatchTruncated: d.cut})
	sum := sha256.Sum256([]byte(system + "\x00" + user))
	key := hex.EncodeToString(sum[:])

	path, err := r.resolveArtifactPath(t.ID, prSummaryDoc(d.Repo))
	if err != nil {
		return ""
	}
	if c, ok := readPRSummary(path); ok && c.Key == key {
		return c.Summary
	}
	call := r.analysisCall(t.ID, "pr_description", 800, prSummaryTimeout)
	if !generate || call == nil {
		return ""
	}

	// One generation per repository at a time: a second request waits and then finds it cached.
	mu, _ := r.prSummaries.LoadOrStore(t.ID+"/"+d.Repo, &sync.Mutex{})
	mu.(*sync.Mutex).Lock()
	defer mu.(*sync.Mutex).Unlock()
	if c, ok := readPRSummary(path); ok && c.Key == key {
		return c.Summary
	}
	ctx, cancel := context.WithTimeout(ctx, prSummaryTimeout)
	defer cancel()
	raw, model, err := call(ctx, system, user)
	if err != nil {
		return ""
	}
	s := pullrequest.CleanSummary(raw)
	if s == "" {
		return ""
	}
	if raw, err := json.MarshalIndent(prSummaryCache{Key: key, Summary: s, Model: model, Generated: time.Now()}, "", "  "); err == nil {
		_ = os.MkdirAll(filepath.Dir(path), 0o755)
		_ = os.WriteFile(path, raw, 0o644)
	}
	return s
}

func readPRSummary(path string) (prSummaryCache, bool) {
	var c prSummaryCache
	raw, err := os.ReadFile(path)
	if err != nil || json.Unmarshal(raw, &c) != nil || c.Summary == "" {
		return c, false
	}
	return c, true
}
